L000453	\section{Master Theorem}
L000454	
L000455	This section provides a detailed proof of our master theorem, which can be formulated as follows.\\
L000456	
L000457	\noindent
L000458	\textbf{Theorem.}
L000459	\emph{
L000460		Let $X_0\in\bC^N$ be given and denote by $(X_n)_{n\geq 0}\in\bC^N$ the sequence generated by the recurrence relation
L000461		\begin{equation}\label{eq:mt:NLEEq}
L000462		X_{n+1} = \sV X_n + \sum_{m=1}^n \sK_m X_{n-m},
L000463		\end{equation}
L000464		where $\sV\in\bC^{N\times N}$ and $(\sK_n)_{n\geq 1}\in\bC^{N\times N}$.
L000465		Assume there exist non-negative constants $v,k,M$ such that \footnote{We note that $M^\ast = M^\ast(k,v)$ is a smooth function in $k$ and $v$.
L000466			Furthermore, the bound $M<M^\ast$ implies $\varepsilon= 4M/(k-v)^2 <1$ in both cases, $v+k<2$ and $v+k\geq 2$.}
L000467		\begin{equation}\label{eq:mt:WMC2}
L000468		k < \min\{v,1\}, \qquad
L000469		M < M^\ast = \begin{cases}(v-k)^2/4, & v+k <2 \\ (1-k)(v-1), & v+k \geq 2\end{cases}
L000470		\end{equation}
L000471		and
L000472		\begin{equation}\label{eq:mt:WMC1}
L000473		\nrm{\sV^{-1}}\leq 1/v, \qquad \nrm{\sK_n}\leq Mk^{n-1},
L000474		\end{equation}
L000475		where $\nrm{\cdot}$ denotes the spectral norm, then the following results hold true.\\
L000476		\textbf{(i)} There exists a unique pair of a non-singular effective generator $\sG\in\bC^{N\times N}$ and a non-singular slippage matrix $\sD\in\bC^{N\times N}$ such that, for any $X_0$,
L000477		\begin{equation}\label{eq:mt:SMAsm}
L000478		\lim_{n\rightarrow\infty}\sG^{-n}X_n = \sD X_0,
L000479		\end{equation}
L000480		and the long-time approximation $Y_n=\sG^n\sD X_0$ satisfies
L000481		\begin{equation}\label{eq:mt:LTAErr}
L000482		\abs{X_n - Y_n}\leq\frac{\zeta-k}{\eta-\zeta}\abs{X_0}\zeta^n,
L000483		\end{equation}
L000484		where $\abs{\cdot}$ indicates the Euclidean norm and
L000485		\begin{equation}\label{eq:mt:ZetEta}
L000486		\zeta = \frac{v+k-\sqrt{(v-k)^2-4M}}{2}<1, \qquad
L000487		\eta  = \frac{v+k+\sqrt{(v-k)^2-4M}}{2}.
L000488		\end{equation}
L000489		\textbf{(ii)} The slippage matrix admits the explicit expression
L000490		\begin{equation}\label{eq:mt:SMDef}
L000491		\sD^{-1} = 1+ \sum_{m=1}^\infty\sum_{n=1}^\infty \sH^{-m}\sK_{m+n-1}\sG^{-n},
L000492		\end{equation}
L000493		where $\sG$ and $\sH$ are the unique solutions of the fixed-point equations
L000494		\begin{align}
L000495		\label{eq:mt:GFPEq}
L000496		\sG &= \sV + \sum_{n=1}^\infty \sK_n\sG^{-n} = T(\sG), \\
L000497		\label{eq:mt:HFPEq}
L000498		\sH &= \sV + \sum_{n=1}^\infty \sH^{-n}\sK_n = U(\sH)
L000499		\end{align}
L000500		in the set $B= \{\sX\in\bC^{N\times N} \; : \; \nrm{\sX^{-1}}\leq 1/\eta\}$.\\
L000501	}
L000502	
L000503	The proof of this theorem follows the approach developed in Refs.~[59, 60] in the main text  for continuous-time dynamics.
L000504	We proceed in four main steps.
L000505	After providing a heuristic derivation of the fixed-point equations~\eqref{eq:mt:GFPEq} and \eqref{eq:mt:HFPEq}, we show that these equations have a unique solution in~$B$.
L000506	In the second step, we demonstrate that the thus identified effective generator~$\sG$ yields a faithful long-time approximation, in the sense that $\lim_{n\rightarrow\infty}\sG^{-n}X_n = \sD X_0$ for any~$X_0$, where~$\sD$ is the slippage matrix defined in Eq.~\eqref{eq:mt:SMDef}.
L000507	The third and fourth steps of our proof establish the bound~\eqref{eq:mt:LTAErr} and the uniqueness of the effective generator and the associated slippage matrix, respectively.
L000508	In the final part of this section, we derive the properties of the memory function and the perturbation scheme discussed towards the end of the main text.
L000509	
L000510	\subsection{Effective Generator}\label{sec:effective_propagator}
L000511	
L000512	To analyze the asymptotic structure of the solutions of Eq.~\eqref{eq:mt:NLEEq}, we define the propagator $(\sZ_n)_{n\geq 0}\in\bC^{N\times N}$ such that $X_n = \sZ_n X_0$ for any $X_0$.
L000513	This sequence satisfies the recursion relation
L000514	\begin{equation}\label{eq:eg:FEEq}
L000515	\sZ_{n+1} = \sV\sZ_n + \sum_{m=1}^n\sK_m\sZ_{n-m}, \qquad
L000516	\sZ_0 = \mathsf{1},
L000517	\end{equation}
L000518	which is equivalent to the adjoint relation
L000519	\begin{equation}\label{eq:eg:BEEq}
L000520	\sZ_{n+1} = \sZ_n\sV + \sum_{m=1}^n\sZ_{n-m}\sK_m, \qquad
L000521	\sZ_0 = \mathsf{1},
L000522	\end{equation}
L000523	as can be verified by noting that both define the same generating function $\hat{\sZ}_s = \sum_{n=0}^\infty \sZ_n s^n=[1-s\sV -s\hat{\sK}_s]^{-1}$, where $\hat{\sK}_s=\sum_{n=1}^\infty\sK_n s^n$.
L000524	Upon inserting the ansatz $\sZ_n = \sG^n\sD + \sR_n$, where $\sG$ and $\sD$ are non-singular, into Eq.~\eqref{eq:eg:FEEq}, we obtain the identity
L000525	\begin{equation}
L000526	\sG = \sV + \sum_{m=1}^n \sK_m \sG^{-m} +
L000527	\biggl(\sV\sR_n + \sum_{m=1}^n\sK_m\sR_{n-m} - \sR_{n+1}\biggr)\sD^{-1}\sG^{-n},
L000528	\end{equation}
L000529	which reduces to the fixed-point equation \eqref{eq:mt:GFPEq} for $n\rightarrow\infty$, provided that the remainder $\sR_n$ decays sufficiently fast in this limit.
L000530	As we shall see in the following, this assumption does not imply additional any conditions; instead, it is fulfilled whenever the weak-memory conditions \eqref{eq:mt:WMC1} and \eqref{eq:mt:WMC2} are satisfied.
L000531	The fixed-point equation \eqref{eq:mt:HFPEq} for the adjoint effective generator $\sH$ can be motivated analogously, using the ansatz $\sZ_n = \sD\sH^n + \sS_n$ and the adjoint recurrence relation \eqref{eq:eg:BEEq}.
L000532	
L000533	Banach's fixed-point theorem makes it possible to prove that these equations have unique solutions in the set $B$ (see Ref.[62] of the main text).
L000534	To this end, we first observe that,  for any non-singular $\sX,\sY\in\bC^{N\times N}$, we have\footnote{This result follows from the bound $\sigma_{i+j-1}(\sX + \sY) \leq \sigma_i(\sX) + \sigma_j(\sY)$, which applies to the ordered singular values $\sigma_1 (\cdot) \geq \cdots \geq \sigma_N(\cdot)$ of any matrices $\sX,\sY\in\bC^{N\times N}$, and implies $\sigma_N(\sX) \geq \sigma_N(\sY) - \sigma_1(\sX- \sY)$ (see Ref. [63] of the main text). Since $\sigma_1(\sX) = \nrm{\sX}$ and $\sigma_N(\sX) = \nrm{\sX^{-1}}^{-1}$, the latter inequality is equivalent to Eq.~\eqref{eq:eg:MatNrmInq}.}
L000535	\begin{equation}\label{eq:eg:MatNrmInq}
L000536	\nrm{\sX^{-1}}^{-1}\geq \nrm{\sY^{-1}}^{-1} - \nrm{\sX-\sY},
L000537	\end{equation}
L000538	where $\lVert \cdot \rVert$ denotes the specatral norm.
L000539	Using this bound, it follows that, for $\sX\in B$,
L000540	\begin{align}
L000541	\nrm{[T(\sX)]^{-1}}^{-1} & \geq \nrm{\sV^{-1}}^{-1} - \nrm{\sum_{n=1}^\infty\sK_n\sX^{-n}}\\
L000542	& \geq v - M\sum_{n=1}^\infty \eta^{-n} k^{n-1} = \eta,\nonumber
L000543	\end{align}
L000544	where we have used that $k<\eta$, since $k<v$.
L000545	Hence, the set $B$ is closed under the map $T$.
L000546	Next, we define the metric $d(\sX,\sY) = \nrm{\sX-\sY}$ and note that
L000547	\begin{equation}
L000548	d(T(\sX),T(\sY))\leq M\sum_{n=1}^\infty \nrm{\sX^{-n}-\sY^{-n}}k^{n-1}.
L000549	\end{equation}
L000550	Thus, upon inserting the identity $\sX^{-n}-\sY^{-n} = \sum_{m=1}^n \sX^{m-n-1}(\sX-\sY)\sY^{-m}$ [64], it follows that for, $\sX,\sY\in B$,
L000551	\begin{equation}
L000552	d(T(\sX),T(\sY)) \leq M d(\sX,\sY) \sum_{n=1}^\infty n \eta^{-n-1}k^{n-1} = qd(\sX,\sY)
L000553	\end{equation}
L000554	with $q = M/(\eta-k)^ 2 = \varepsilon/(1+\sqrt{1-\varepsilon})^2$, where $\varepsilon=4M/(v-k)^ 2$.
L000555	Since the conditions \eqref{eq:mt:WMC2} imply $\varepsilon<1$, and thus $q<1$, we can conclude that $T$ is a contraction on the closed metric space $(B,d)$.
L000556	Therefore, the fixed-point equation $\sG = T(\sG)$ has a unique solution in $B$.
L000557	The same result holds true for the second fixed-point equation $\sH = U(\sH)$, as can be verified along the same lines.
L000558	
L000559	We conclude this section by noting that the two effective generators $\sG$ and $\sH$ defined above and the slippage matrix $\sD$ defined in Eq.~\eqref{eq:mt:SMDef} satisfy the intertwining relation
L000560	\begin{equation}\label{eq:eg:IntRel}
L000561	\sG\sD = \sD\sH,
L000562	\end{equation}
L000563	which can be derived in two steps.
L000564	First, we observe that the fixed-point equations \eqref{eq:mt:GFPEq} and \eqref{eq:mt:HFPEq} imply
L000565	\begin{align}\label{eq:eg:IntRelAux}
L000566	\sD^{-1}\sG & = \sG + \sum_{m=1}^\infty\sH^{-m}\sK_m + \sum_{n=1}^\infty\sum_{m=1}^\infty
L000567	\sH^{-m}\sK_{m+n}\sG^{-n}\\
L000568	& = \sH + \sum_{n=1}^\infty\sK_n\sG^{-n}  + \sum_{n=1}^\infty\sum_{m=1}^\infty
L000569	\sH^{-m}\sK_{m+n}\sG^{-n}
L000570	= \sH\sD^{-1}. \nonumber
L000571	\end{align}
L000572	Second, since $\sG,\sH\in B$, the bound
L000573	\begin{align}
L000574	\label{eq:eg:DBnd}
L000575	\nrm{\sD^{-1}-1} \leq \sum_{n=1}^\infty\sum_{m=1}^\infty\nrm{\sH^{-m}\sK_{m+n-1}\sG^{-n}} \leq M \sum_{n=1}^\infty\sum_{m=1}^\infty \eta^{-m-n}k^{m+n-2} = q <1
L000576	\end{align}
L000577	holds, which shows that $\sD^{-1}$ is non-singular; hence, so is $\sD$.
L000578	Therefore, the relations \eqref{eq:eg:IntRelAux} and \eqref{eq:eg:IntRel} are equivalent.
L000579	
L000580	\subsection{Slippage Matrix}
L000581	
L000582	\newcommand{\vphp}{\vphantom{\prime}}
L000583	
L000584	We take $\sG$ to be the solution of the fixed-point equation \eqref{eq:mt:GFPEq} in $B$.
L000585	Our aim is to show that $\lim_{n\rightarrow\infty} \sG^{-n}\sZ_n = \sD$, where $\sD$ is the slippage matrix defined in Eq.~\eqref{eq:mt:SMDef}.
L000586	To this end, we define the reduced propagator $\sA_n = \sG^{-n}\sZ_n$.
L000587	This sequence satisfies the recurrence relation
L000588	\begin{align}
L000589	\label{eq:lta:rp:RedProRecRel}
L000590	\sA_{n+1} & = \sG^{-1}\sA_n\sV + \sum_{m=0}^{n-1}\sG^{m-n-1}\sA_m\sK_{n-m}\\
L000591	& = \sG^{-1}\sA_n\sG + \sum_{m=0}^{n-1}\sG^{m-n-1}\sA_m\sK_{n-m}
L000592	- \sum_{m=1}^\infty \sG^{-1}\sA_n\sK_m\sG^{-m},
L000593	\qquad \sA_0 = \mathsf{1}, \nonumber
L000594	\end{align}
L000595	which can be derived by first inserting the adjoint evolution equation \eqref{eq:eg:BEEq} for the propagator $\sZ_n$, and then eliminating the free generator $\sV$ using Eq.~\eqref{eq:mt:GFPEq}.
L000596	Using this result, the asymptotic behavior of the reduced propagator can be analyzed as follows.
L000597	We first apply the transformation $\tilde{\sA}_n = \sG^n\sA_n\sG^{-n}$ and observe that
L000598	\begin{equation}
L000599	\tilde{\sA}_{n+1} - \tilde{\sA}_n = \sum_{m=0}^{n-1}\tilde{\sA}_m\sG^m\sK_{n-m}\sG^{-n-1}
L000600	-\sum_{m=1}^\infty\tilde{\sA}_n\sG^n\sK_m\sG^{-n-m-1},
L000601	\qquad \tilde{\sA}_0 = \mathsf{1}.
L000602	\end{equation}
L000603	Summing both sides of this equation over $n$ shows that
L000604	\begin{equation}\label{eq:lta:RedProRecRel_2}
L000605	\sA_n = 1 -\sum_{m=0}^{n-1}\sum_{l=n-m-1}^\infty\sG^{m-n}\sA_m\sK_{l+1}\sG^{n-m-l-2}.
L000606	\end{equation}
L000607	Next, we define the shifted sequence $\sA'_n = \sA_n^{\vphp}-\sD$, which follows the recurrence relation
L000608	\begin{align}
L000609	\sA'_n & = 1 - \sD\biggl(1
L000610	+ \sum_{m=1}^{n}\sum_{l=1}^\infty\sH^{-m}\sK_{m+l-1}^{\vphp}\sG^{-l}\biggr)
L000611	- \sum_{m=0}^{n-1}\sum_{l=n-m-1}^\infty\sG^{m-n}\sA'_m\sK_{l+1}^{\vphp}\sG^{n-m-l-2}\\
