L000614	\nonumber
L000615	\end{align}
L000616	Here, we have first used the intertwining relation \eqref{eq:eg:IntRel} and then inserted the definition \eqref{eq:mt:SMDef} of $\sD$.
L000617	Since $\sG,\sH\in B$, this result leads to the recursive bound
L000618	\begin{align}
L000619	\nrm{\sA'_n} & \leq \nrm{\sD}\sum_{m=n}^\infty\sum_{l=m}^\infty
L000620	\nrm{\sH^{-m-1}\sK_{l+1}^{\vphp}\sG^{m-l-1}}+ \sum_{m=0}^{n-1}\sum_{l=n-m-1}^\infty
