L000650	\subsection{Error Bound}
L000651	
L000652	To derive the bound \eqref{eq:mt:LTAErr}, we define the memory function $\sE_n = \sG^{n+1}(\sA_{n+1} -\sA_n)$.
L000653	This sequence satisfies the recurrence relation
L000654	\begin{equation}
L000655	\sE_n =  - \sum_{m=n}^\infty\sK_{m+1}\sG^{n-m-1}
L000656	- \sum_{m=0}^{n-1}\sum_{l=m}^\infty\sE_{n-m-1}\sK_{l+1}\sG^{m-l-1},
L000657	\qquad \sE_0 = \sV - \sG,
L000658	\end{equation}
L000659	which follows from the recurrence relation for the reduced propagator \eqref{eq:lta:RedProRecRel_2}, and implies the recursive bound
L000660	\begin{align}
L000661	\nrm{\sE_n} & \leq \sum_{m=n}^\infty \nrm{\sK_{m+1}\sG^{n-m-1}}
L000662	+ \sum_{m=0}^{n-1}\sum_{l=m}^\infty\nrm{\sE_{n-m-1}\sK_{l+1}\sG^{m-l-1}}\\
L000663	& \leq M\sum_{m=n}^\infty \eta^{n-m-1}k^m + M\sum_{m=0}^{n-1}\sum_{l=m}^\infty
L000664	\nrm{\sE_{n-m-1}}\eta^{m-l-1}k^l\nonumber\\
L000665	&=\frac{Mk^n}{\eta-k} + \frac{M}{\eta-k}\sum_{m=0}^{n-1}\nrm{\sE_{n-m-1}}k^m\nonumber
L000666	\end{align}
L000667	with
L000668	\begin{align}
L000669	\nrm{\sE_0} = \nrm{\sV-\sG} & \leq \sum_{n=1}^\infty\nrm{\sK_n\sG^{-n}}
L000670	\leq M \sum_{n=1}^\infty \eta^{-n}k^{n-1}
L000671	= \frac{M}{\eta-k}=\zeta- k.
L000672	\end{align}
L000673	Here, we have used the parameters $\zeta$ and $\eta$ being defined in Eq.~\eqref{eq:mt:ZetEta}, and the fact that $(\eta-k)(\zeta-k)=M$.
L000674	Consequently, we have
L000675	\begin{equation}\label{eq:eb:CMFBnd}
L000676	\nrm{\sE_n} \leq (\zeta-k)\zeta^n,
L000677	\end{equation}
L000678	as can again be shown by induction.
L000679	Next, we note that, by construction, $\sA_n = 1+\sum_{m=1}^n\sG^{-m}\sE_{m-1}$.
L000680	Thus, the slippage matrix must be given by $\sD= 1+\sum_{m=1}^\infty\sG^{-m}\sE_{m-1}$, and the error of the long-time approximation $Y_n = \sG^n\sD X_0$ of $X_n$ can be expressed as
L000681	\begin{align}
L000682	\abs{X_n - Y_n} = \abs{\sG^n(\sA_n - \sD)X_0}
L000683	& \leq \abs{X_0}\sum_{m=n+1}^\infty\nrm{\sG^{n-m}\sE_{m-1}}\\
L000684	& \leq (\zeta-k)\abs{X_0}\sum_{m=n+1}^\infty\eta^{n-m}\zeta^{m-1}
L000685	= \frac{\zeta-k}{\eta-\zeta}\abs{X_0}\zeta^n, \nonumber
L000686	\end{align}
L000687	where we have used that the matrix norm $\nrm{\cdot}$ and the vector norm $\abs{\cdot}$ are consistent.
L000688	
L000689	\subsection{Uniqueness}
L000690	
L000691	To establish the uniqueness of the effective generator, we let $\bar{\sG}\in\bC^{N\times N}$ be a non-singular matrix such that $\sZ_n = \bar{\sG}^n\bar{\sA}_n$ and the sequence $(\bar{\sA}_n)_{n\geq 0}\in\bC^{N\times N}$ converges to a non-singular matrix $\bar{\sD}\in\bC^{N\times N}$ in the limit $n\rightarrow\infty$.
L000692	We assume that $\bar{\sG}\neq\sG$ and $\bar{\sD}\neq\sD$.
L000693	However, since the propagator is unique, we must still have $\bar{\sG}^n\bar{\sA}_n = \sG^n\sA_n$.
L000694	By assumption, the sequence $\sS_n = \bar{\sG}^{-n}\sG^n=\bar{\sA}_n^{\vphantom{1}}\sA^{-1}_n$ converges to a non-singular matrix $\sS = \bar{\sD}\sD^{-1}$ for $n\rightarrow\infty$.
L000695	Consequently, we have
L000696	\begin{equation}
L000697	0 = \lim_{n\rightarrow\infty}\bigl(\sS_{n+1}-\sS_n\bigr)
L000698	= \lim_{n\rightarrow\infty}\bigl(\bar{\sG}^{-1}\sS_n\sG - \sS_n\bigr)
L000699	= \bar{\sG}^{-1}\sS\sG - \sS.
L000700	\end{equation}
L000701	Hence, $\sG$ and $\bar{\sG}=\sS\sG\sS^{-1}$ are similar to each other.
L000702	Next, we define $\bar{Y}_n = \bar{\sG}^n\bar{\sD}X_0= \sS\sG^n\sD X_0$ and note that
L000703	\begin{equation}\label{eq:uq:SubBnd}
L000704	\abs{X_n-\bar{Y}_n}\geq \bigl|\abs{\bar{Y}_n-Y_n}-\abs{X_n-Y_n}\bigr|,
L000705	\end{equation}
L000706	where $Y_n = \sG^n\sD X_0$ is the canonical long-time approximation that satisfies the bound \eqref{eq:mt:LTAErr}.
L000707	Since $\sD$ is non-singular, and $\sS-1 \neq 0$ by assumption there exist an initial state $X_0\neq 0$ and a constant $C>0$ such that\footnote{To derive this result, first assume that $\sG$ has an eigenvector $G^j_1$ with corresponding eigenvalue $\gamma_j$ such that $(1-\sS)G^1_j\neq0$.
L000708		Setting $\sD X_0 = G^1_j$ then yields $ \abs{(\sS-1)\sG^n\sD X_0}= \abs{(\sS-1)G^1_j}\abs{\gamma_j^{\vphantom{1}}}^n \geq \abs{(\sS-1)G^1_j}\eta^n$,
L000709		where the last inequality follows from the condition $\nrm{\sG^{-1}}\leq 1/\eta$.
L000710		If $(\sS-1)G^1_j=0$ for all eigenvectors of $\sG$, assume that $\sG$ has a generalized eigenvector $G^2_j$ of rank $2$ such that $(\sS-1)G^2_j\neq 0$.
L000711		Since $\sG G^2_j = \gamma^{\vphantom{1}}_jG^2_j+G^1_j$ and $(1-\sS)G^1_j =0$, we then have $(\sS-1)\sG^n G^2_j = \abs{\gamma^{\vphantom{1}}_j}^n(\sS-1)G^2_j$, and the result \eqref{eq:uq:DevBnd} follows by setting $\sD X_0 = G^2_j$.
L000712		If $(\sS-1)G^1_j = (\sS-1)G^2_j =0$ for all $j$, the above argument can be repeated with generalized eigenvectors of successively higher rank.
L000713		Since the proper and generalized eigenvectors of $\sG$ together form a complete basis, and $\sS-1\neq 0$, there must eventually exist a $G^m_j$ such that $(\sS-1)G^m_j \neq 0$.
L000714	}
L000715	\begin{align}
L000716	\label{eq:uq:DevBnd}
L000717	\abs{\bar{Y}_n - Y_n} = \abs{(\sS-1)\sG^n\sD X_0}  \geq C\eta^n
L000718	\end{align}
L000719	Upon recalling Eq.~\eqref{eq:uq:SubBnd} and the bound \eqref{eq:mt:LTAErr} on the error of the canonical long-time approximation $Y_n$, and using, this observation implies
L000720	\begin{equation}
L000721	\abs{X_n-\bar{Y}_n}\geq C \eta^n- \frac{\zeta-k}{\eta-\zeta}\abs{X_0}\zeta^n,
L000722	\end{equation}
L000723	where we have used that $\eta > \zeta$.
L000724	This result shows that, for any effective generator $\bar{\sG}\neq\sG$ that gives rise to a faithful long-time approximation, $\bar{Y}_n\neq Y_n$, there exist initial states $X_0$ such that
L000725	\begin{equation}
L000726	\lim_{n\rightarrow\infty}\abs{X_n - \bar{Y}_n}\sigma^{-n} = \infty
L000727	\end{equation}
L000728	for any $\sigma<\eta$.
L000729	That is, if $\sG$ is non-singular and the asymptotic relation \eqref{eq:mt:SMAsm} is satisfied with a non-singular slippage matrix $\sD$, then the bound \eqref{eq:mt:LTAErr} holds for any $X_0$ if and only if $\sG$ is the unique solution of the fixed-point equation \eqref{eq:mt:GFPEq} in the set $B$ defined after Eq.~\eqref{eq:mt:HFPEq}, and the slippage matrix is given by Eq.~\eqref{eq:mt:SMDef}.
L000730	The proof of our master theorem is therefore complete.
