L000732	\subsection{Memory Function}
L000733	
L000734	\newcommand{\vphx}{\vphantom{\sX}}
L000735	
L000736	For $\sX\in\bC^{N\times N}$, we define the memory function $(\sE_n(\sX))_{n\geq 0}\in\bC^{N\times N}$ such that the propagator of Eqs.~\eqref{eq:eg:FEEq} and \eqref{eq:eg:BEEq} satisfies the inhomogeneous recurrence relation
L000737	\begin{equation}\label{eq:mf:MFDef}
L000738	\sZ_{n+1} = \sX\sZ_n + \sE_n(\sX), \qquad \sZ_0 = \mathsf{1}.
L000739	\end{equation}
L000740	This condition implies that $\sE_n(\sX)$ is uniquely determined by the initial-value problem\footnote{This result follows by comparing the Laplace space solutions of Eq.~\eqref{eq:mf:MFDef}, $\hat{\sZ}_s= [1-s\hat{\sX}]^{-1}(1+s\hat{\sE}_s(\sX))$, and Eqs.~\eqref{eq:eg:FEEq} and \eqref{eq:eg:BEEq}, $\hat{\sZ}_s= [1-s\sV-s\hat{\sK}_s]^{-1}$, where $\hat{\sZ}_s =\sum_{n=0}^\infty\sZ_n s^n$, $\hat{\sK}_s = \sum_{n=1}^\infty \sK_n s^n$ and $\hat{\sE}_s(\sX)= \sum_{n=0}^\infty \sE_n(\sX)s^n$.}
L000741	\begin{equation}\label{eq:mf:MFRec}
L000742	\sE_{n+1}(\sX) = \sK_{n+1} + \sE_n(\sX)\sV + \sum_{m=1}^n\sE_{n-m}(\sX)\sK_m,
L000743	\qquad \sE_0(\sX) = \sV - \sX.
L000744	\end{equation}
L000745	In the following, we establish two key properties of the sequence $\sE_n(\sX)$.
L000746	First, the bound \eqref{eq:eb:CMFBnd} applies only to the canonical memory function $\sE_n(\sG) = \sE_n$.
L000747	Second, if $\sX\neq\sG$, the asymptotic relation
L000748	\begin{equation}
L000749	\limsup_{n\rightarrow\infty} \nrm{\sE_n(\sX)}\sigma^{-n} = \infty
L000750	\end{equation}
L000751	holds for any $\sigma<\eta$.
L000752	Upon recalling that the bound $\nrm{\sE_n}\leq (\zeta-k)\zeta^n$ holds for the canonical memory function, and that $\eta>\zeta$, it follows that the canonical effective generator $\sG$ is unique in that it corresponds to the fastest decaying memory function.
L000753	
L000754	To derive these results, we first convert the initial-value problem \eqref{eq:mf:MFRec} into a final-value problem by introducing the sequence $\tilde{\sE}_n(\sX) = \sE_n(\sX)\sV^{-n}$, which satisfies
L000755	\begin{equation}\label{eq:mf:MFTrsRec}
L000756	\tilde{\sE}_{n+1}(\sX)-\tilde{\sE}_n(\sX) = \sK_{n+1}\sV^{-n-1}
L000757	+\sum_{m=1}^n \tilde{\sE}_{n-m}(\sX)\sV^{n-m}\sK_m\sV^{-n-1}, \qquad
L000758	\tilde{\sE}_0(\sX)=\sV -\sX.
L000759	\end{equation}
L000760	Next, for any $0<S$ and $0<\sigma<1$, we define a set of rapidly decaying sequences,
L000761	\begin{equation}
L000762	\fB_{S,\sigma}
L000763	= \bigl\{(\sX_n)_{n\geq 0}\in\bC^{N\times N} \; : \; \nrm{\sX_n}\leq S\sigma^n\bigr\}.
L000764	\end{equation}
L000765	If $\sE_n(\sX)\in\fB_{S,\sigma}$ with $\sigma<v$, we have $\lim_{n\rightarrow\infty}\tilde{\sE}_n(\sX) = 0$ and, upon summing over $n$, Eq.~\eqref{eq:mf:MFTrsRec} implies
L000766	\begin{align}
L000767	\sE_n(\sX)  = -\sum_{m=n}^\infty\sK_{m+1}\sV^{n-m-1}
L000768	-\sum_{m=n}^\infty\sum_{l=1}^m\sE_{m-l}(\sX)\sK_l\sV^{n-m-1}
L000769	= \fT_n[\sE(\sX)],\
L000770	\end{align}
L000771	where $\fT$ defines a linear map on the space of matrix-valued sequences.
L000772	We now observe that, for $\sX\in\fB_{S,\sigma}$,
L000773	\begin{align}
L000774	\nrm{\fT_n[\sX]} & \leq \sum_{m=n}^\infty\nrm{\sK_{m+1}}\sV^{n-m-1}
L000775	+ \sum_{m=n}^\infty\sum_{l=1}^m\nrm{\sX_{m-l}\sK_l\sV^{n-m-1}}\\
L000776	& \leq M \sum_{m=n}^\infty k^{m}v^{n-m-1} + MS\sum_{m=n}^\infty\sum_{l=1}^m
L000777	k^{l-1} v^{n-m-1}\sigma^{m-l}\nonumber\\
L000778	& =\frac{M}{\sigma-k}\biggl(\frac{S\sigma^n}{v-\sigma}-\frac{(k-\sigma+S)k^n}{v-k}\biggr),
L000779	\nonumber
L000780	\end{align}
L000781	where we have again used the assumption $\sigma<v$.
L000782	Upon further restricting the parameters $S$ and $\sigma$ such that
L000783	\begin{equation}\label{eq:mf:RDPCls}
L000784	S\geq \sigma -k \quad\text{and}\quad \zeta \leq \sigma < \min\{\eta,1\},
L000785	\end{equation}
L000786	with the parameters $\zeta$ and $\eta$ defined in Eq.~\eqref{eq:mt:ZetEta}, we obtain the bound
L000787	\begin{equation}
L000788	\nrm{\fT_n[\sX]}\leq \frac{M S\sigma^n}{(\sigma-k)(v-\sigma)} \leq S\sigma^n.
L000789	\end{equation}
L000790	That is, for any $S$ and $\sigma$ satisfying the conditions \eqref{eq:mf:RDPCls}, $\fT$ maps the set $\fB_{S,\sigma}$ of rapidly decaying sequences into itself.
L000791	For the next step of our derivation, we equip each set $\fB_{S,\sigma}$ with a metric,
L000792	\begin{equation}
L000793	d_\mu(\sX,\sY) = \sup_{n\geq 0}\nrm{\sX_n-\sY_n}\mu^{-n}
L000794	\quad\text{with}\quad \mu\geq \sigma.
L000795	\end{equation}
L000796	We then have
L000797	\begin{align}
L000798	d_\mu (\fT[\sX],\fT[\sY]) & \leq \sup_{n\geq 0} \sum_{m=n}^\infty\sum_{l=1}^m
L000799	\nrm{(\sX_{m-l} - \sY_{m-l})\sK_l\sV^{n-m-1}}\mu^{-n}\\
L000800	&\leq M d_\mu(\sX,\sY)\sup_{n\geq 0}
L000801	\sum_{m=n}^\infty\sum_{l=1}^m k^{l-1} v^{n-m-1}\mu^{m-l-n}\nonumber\\
L000802	&= M d_\mu(\sX,\sY) \sup_{n\geq 0} \frac{1}{\mu-k}
L000803	\biggl(\frac{1}{v-\mu}-\frac{k^n\mu^{-n}}{v-k}\biggr).\nonumber
L000804	\end{align}
L000805	for any $\sX_n,\sY_n\in\fB_{S,\sigma}$ and any $\mu<v$.
L000806	Thus, if we further restrict $\mu$ such that $k<\mu<v$, it follows that
L000807	\begin{equation}
L000808	d_\mu (\fT[\sX],\fT[\sY]) \leq q_\mu d_\mu(\sX,\sY),
L000809	\end{equation}
L000810	where the Lipschitz constant $q_\mu = M/(\mu-k)(v-\mu)$ becomes strictly smaller than $1$ if $\zeta < \mu < \eta$.
L000811	That is, for any $S$ and $\sigma$ satisfying the conditions \eqref{eq:mf:RDPCls}, there exists a $\mu\geq \sigma$ such that the map $\fT$ becomes a contraction on $\fB_{S,\sigma}$ with respect to the metric $d_\mu$.
L000812	Since $(d_\mu, \fB_{S,\sigma})$ is a complete metric space, it follows from Banach's fixed-point theorem that any admissible set $\fB_{S,\sigma}$ contains exactly one solution of the fixed-point equation $\fT_n[\sX] = \sX_n$ [62].
L000813	
L000814	This result has two main implications for our theory.
L000815	First, the set $\fB_{k-\zeta,\zeta}$ contains only the canonical memory function $\sE_n = \sE_n(\sG)$.
L000816	Second, since the correspondence between $\sX$ and $\sE_n(\sX)$ is one-to-one, the bound $\nrm{\sE_n(\sX)}\leq S\sigma^n$, must be violated for any $\sX\neq\sG$ as long as $S$ and $\sigma$ satisfy the conditions \eqref{eq:mf:RDPCls}.
L000817	That is, there must exist an $n\geq 0$ such that
L000818	\begin{equation}
L000819	\nrm{\sE_n(\sX)} > S\sigma^n.
L000820	\end{equation}
L000821	Since $S$ can be chosen arbitrary large, and $\nrm{\sE_n}<\infty$ for any finite $n$, this condition can only be met if
L000822	\begin{equation}
L000823	\limsup_{n\rightarrow\infty} \nrm{\sE_n(\sX)}\sigma^{-n} = \infty
L000824	\end{equation}
L000825	for any admissible $\sigma<\min\{\eta,1\}$.
L000826	
L000827	We conclude this section by noting that the mathematical structure developed above is useful for perturbative calculations.
L000828	Specifically, if an initial guess $\sE^0_n\in\fB_{S,\sigma}$ for the canonical memory function is know, where $S$ and $\sigma$ satisfy the conditions \eqref{eq:mf:RDPCls}, then $\sE_n^{\vphantom{\ell}}=\lim_{\ell\rightarrow\infty}\sE^\ell_n$ can be arbitrary well approximated by iterating the map $\fT$, that is, by evaluating $\sE_n^{\ell +1} = \fT_n^{\vphantom{\ell}}[\sE^\ell_{\vphantom{n}}]$.
L000829	Once the memory function has been obtained to sufficient accuracy, the corresponding effective generator and slippage matrix can be recovered through the relations
L000830	\begin{equation}
L000831	\sG = \sV -\sE_0 \quad\text{and}\quad \sD = 1 + \sum_{n=1}^\infty\sG^{-n}\sE_{n-1}.
L000832	\end{equation}
L000833	In particular, for $\sE_n^0=0$, we obtain a uniformly convergent series expansion $\sE_n^{\vphantom{\ell}} = \sum_{\ell=1}^\infty \sE^{(\ell)}_n$ of the canonical memory function in the memory strength, where
L000834	\begin{equation}
L000835	\sE_n^{(1)} = -\sum_{m=n}^\infty \sK_{m+1}^{\vphantom{(\ell)}}\sV^{n-m-1}
L000836	\quad\text{and}\quad
L000837	\sE^{(\ell+1)}_n = - \sum_{m=n}^\infty\sum_{l=1}^m \sE_{m-l}^{(\ell)}\sK_l^{\vphantom{(\ell)}}\sV^{n-m-1}.
L000838	\end{equation}
L000839	Hence, $\sE^{(\ell)}_n$ is of order $\ell$ in the memory kernel, and thus of order $\ell$ in the coupling strength $M$, which enters the weak-memory conditions \eqref{eq:mt:WMC1} through the bound $\nrm{\sK_n}\leq Mk^{n-1}$.
