L000842	\section{Application 1: Mesoscopic Charge Pump}
L000843	
L000844	This section contains details on the stochastic pump model presented in the main text.
L000845	We first provide a brief recap the projection operator formalism used to derive the equation of motion for the lumped state, and then move on to the specifics of the model discussed in the main text.
L000846	
L000847	\subsection{Projection Operators}
L000848	
L000849	We consider a system with a discrete space of microstates $\mathbb{M}=\{1,\dots,M\}$, whose state is described by the probability vector $P_n =[P^1_n,\dots, P^M_n]^\sT$.
L000850	This vector evolves according to the discrete-time master equation
L000851	\begin{equation}
L000852	\label{eq:markov_jump}
L000853	P_{n+1} = \sL P_{n},
L000854	\end{equation}
L000855	where $\sL$ is a stochastic matrix, i.e., $(\sL)_{ij}\geq 0$ and $\sum_j (\sL)_{ij} =1$.
L000856	Without loss of generality, we assume that the microstates are arranged in blocks of $N$ disjoint mesostates $\mathbb{M}_\alpha\subset\mathbb{M}$, each of which contains $M_\alpha$ microstates.
L000857	The occupation probabilities of these mesostates are collected in the lumped state vector $X_n = [X^1_n,\dots,X^N_n]^\sT = \sM P_n$.
L000858	Here, the matrix
L000859	\begin{equation}\label{eq:sp:DTME}
L000860	\sM = \bigoplus_{\alpha=1}^N (1_\alpha)^\sT
L000861	\end{equation}
L000862	projects the space of microstates onto the space of mesostates, where $1_{\alpha}$ denotes the all-ones vector of size $M_\alpha$;
L000863	that is, $X^\alpha_n = \sum_{i\in\mathbb{M}_\alpha}P^i_n$.
L000864	
L000865	To derive an equation of motion for $X_n$, we fix a reference probability vector $R_\alpha^{\vphantom{M_\alpha}}=[R^{1\vphantom{M_\alpha}}_\alpha,\dots,R^{M_\alpha}_\alpha]^\sT$ for every mesostate and define the matrix
L000866	\begin{equation}
L000867	\sM^\ast = \bigoplus_{\alpha=1}^N R_\alpha
L000868	\end{equation}
L000869	such that $\sM\sM^\ast=\mathsf{1}$ is the identity matrix of size $N$ and $\sM^\ast\sM=\sP$ is a projection matrix of size $M$.
L000870	Upon defining the relevant and irrelevant parts of the microscopic state vector as $P_n^\parallel = \sP P_n$ and $P_n^\perp = \sQ P_n$, respectively, where $\sQ = 1-\sP$, Eq.~\eqref{eq:sp:DTME} can be rewritten as a set of two coupled recursion relations,
L000871	\begin{align}
L000872	\label{eq:sp:xnpar}
L000873	P_{n+1}^\parallel & = \sP\sL P_n^{\parallel} + \sP\sL P_n^\perp, \\
L000874	\label{eq:sp:xnperp}
L000875	P_{n+1}^\perp & = \sQ\sL P_n^{\parallel} + \sQ\sL P_n^\perp.
L000876	\end{align}
L000877	Recursively substituting the second of these equations into the first yields the closed evolution equation
L000878	\begin{equation}
L000879	\label{eq:xnpar_2}
L000880	P_{n+1}^\parallel = \sP\sL P_n^{\parallel} + \sP\sL \sum_{m=1}^{n} (\sQ\sL)^{m} P_{n-m}^\parallel + \sP\sL (\sQ\sL)^n P^\perp_0
L000881	\end{equation}
L000882	for $P^\parallel_n$, which, upon recalling that $\sM P^\parallel_n = \sM P_n = X_n$, can be reduced to the lower-dimensional recurrence relation
L000883	\begin{equation}\label{eq:sp:NLEEQ}
L000884	X_{n+1} = \sV X_n +  \sum_{m=1}^{n} \sK_m X_{n-m} + x_n
L000885	\quad\text{with}\quad
L000886	\sV = \sM\sL\sM^* \quad\text{and}\quad
L000887	\sK_{n} = \sM\sL(\sQ\sL)^{n}\sM^*.
L000888	\end{equation}
